import numpy as np
X = np.array([[0, 1], [1, 0]]); Z = np.diag([1., -1.]); I2 = np.eye(2)
def op(o, i, n):
    m = np.eye(1)
    for k in range(n): m = np.kron(m, o if k == i else I2)
    return m
def reservoir(n=4, h=1.0, dt=10.0, V=5, seed=1):
    r = np.random.default_rng(seed); H = np.zeros((2**n, 2**n))
    for i in range(n):
        for j in range(i + 1, n): H += r.uniform(-0.5, 0.5) * op(X, i, n) @ op(X, j, n)
    for i in range(n): H += h * op(Z, i, n)
    E, Q = np.linalg.eigh(H)
    return Q @ np.diag(np.exp(-1j * E * dt / V)) @ Q.T, [np.diag(op(Z, i, n)) for i in range(n)]
def features(s, n=4, V=5):
    U, Zd = reservoir(n, V=V); D = 2**n; rho = np.eye(D) / D; F = []
    for x in s:
        r4 = rho.reshape(2, D // 2, 2, D // 2); rest = r4[0, :, 0, :] + r4[1, :, 1, :]
        psi = np.array([np.sqrt(1 - x), np.sqrt(x)]); rho = np.kron(np.outer(psi, psi), rest)
        f = []
        for _ in range(V):
            rho = U @ rho @ U.conj().T; p = np.real(np.diag(rho)); f += [z @ p for z in Zd]
        F.append(f)
    return np.array(F)
def mc(F, s, w=200, tr=800, dmax=12):
    A = np.hstack([F, np.ones((len(F), 1))]); tot = 0
    for d in range(1, dmax + 1):
        y = s[w - d:len(s) - d]; Atr, Ate = A[w:w + tr], A[w + tr:]
        wts = np.linalg.solve(Atr.T @ Atr + 1e-6 * np.eye(A.shape[1]), Atr.T @ y[:tr])
        tot += np.corrcoef(Ate @ wts, y[tr:])[0, 1]**2
    return tot
rng = np.random.default_rng(0); s = rng.uniform(0, 1, 1400)
F = features(s)
print(f"exact features: MC = {mc(F, s):.2f}")
for S in [10, 100, 1000, 10000, 100000]:
    vals = []
    for rep in range(3):
        noise = rng.normal(size=F.shape) * np.sqrt((1 - F**2) / S)
        vals.append(mc(F + noise, s))
    print(f"S = {S:>6} shots: MC = {np.mean(vals):.2f}")
print(f"spread of the features over time: std <Z_i> = {F.std(axis=0).mean():.3f}")
